let cart=[],currentProduct=null,config={},step=1,selectedDestination='',selectedMomentTheme='';const grid=document.getElementById('productGrid');
function renderProducts(filter='all'){grid.innerHTML=products.map(p=>`<article class="product-card ${filter!=='all'&&p.category!==filter?'is-hidden':''}"><div class="product-visual ${p.visual}" data-product="${p.id}" role="button" tabindex="0" aria-label="${p.travelOnly?'Ver libros de viaje':'Personalizar '+p.title}"><span class="pill">${p.pill}</span></div><div class="product-info"><h3 data-product="${p.id}" tabindex="0">${p.title}</h3><p>${p.desc}</p><div class="product-meta"><span class="product-price">Desde $${p.price.toFixed(2)} AUD</span><button class="product-cta" data-product="${p.id}">${p.travelOnly?'Ver destinos ↗':'Personalizar ↗'}</button></div></div></article>`).join('');grid.querySelectorAll('[data-product]').forEach(b=>{const action=()=>b.dataset.product==='travelbooks'?showTravelCatalog():openCustomizer(b.dataset.product);b.addEventListener('click',action);b.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();action()}})})}renderProducts();
document.querySelectorAll('.tab').forEach(tab=>tab.addEventListener('click',()=>{const filter=tab.dataset.filter;document.querySelectorAll('.tab').forEach(t=>t.classList.remove('active'));tab.classList.add('active');renderProducts(filter);document.getElementById('viajes-catalogo')?.classList.toggle('is-hidden',filter==='decor'||filter==='gifts')}));document.getElementById('menuToggle').addEventListener('click',()=>document.querySelector('.main-nav').classList.toggle('open'));
function openModal(id){const el=document.getElementById(id);el.classList.add('open');el.setAttribute('aria-hidden','false');document.body.style.overflow='hidden'}function closeModal(id){const el=document.getElementById(id);el.classList.remove('open');el.setAttribute('aria-hidden','true');document.body.style.overflow=''}document.querySelectorAll('[data-close]').forEach(b=>b.addEventListener('click',()=>closeModal(b.dataset.close)));
function openCustomizer(id,travel=false){currentProduct=products.find(p=>p.id===id);currentProduct._baseTitle??=currentProduct.title;if(travel)currentProduct.title=selectedMomentTheme?'Fotolibro · Wedding':`Libro de viaje · ${selectedDestination||'tu destino'}`;else currentProduct.title=currentProduct._baseTitle;step=1;config={size:travel?'A4 vertical':currentProduct.sizes[0],finish:currentProduct.finishes[0],pages:currentProduct.pages[0]||'',paper:'Fedrigoni Free Life Satin 150gsm',coverMaterial:'Leather · Ebony',stamping:'Gold Foil',font:'Helvetica · 36 points',accessory:'Sin accesorio',shape:'Square',pack:'Set of 8',holder:'Sin soporte',travel:!!travel,moment:!!selectedMomentTheme,momentTheme:selectedMomentTheme||'',destination:selectedMomentTheme?'Wedding':(selectedDestination||'Australia'),files:[],name:''};renderStep();openModal('customizer')}
function renderStep(){const p=currentProduct;document.querySelectorAll('.stepper span').forEach((x,i)=>x.classList.toggle('current',i===step-1));const body=document.getElementById('customizerBody');if(step===1){body.innerHTML=`<p class="eyebrow">Paso 1 de 4</p><h2 class="modal-title">Empieza con ${p.title}</h2><p class="modal-subtitle">Elige la configuración base. Podrás revisar todo antes de pagar.</p><label class="field"><span>Tamaño / formato</span><select id="sizeSelect">${p.sizes.map(x=>`<option ${x===config.size?'selected':''}>${x}</option>`).join('')}</select></label><p class="field"><span>Acabado</span></p><div class="option-grid">${p.finishes.map(x=>`<button class="option finish-option ${x===config.finish?'selected':''}" data-key="finish" data-value="${x}"><span class="finish-photo finish-${x.toLowerCase()}"></span><strong>${x}</strong><small>${x==='Mate'?'Textura suave, menos reflejo':x==='Lino'?'Textura textil, cálida y natural':x==='Gloss coating'?'Capa protectora brillante y fácil de limpiar':'Colores más brillantes'}</small></button>`).join('')}</div>${p.pages.length?`<label class="field"><span>Páginas</span><select id="pagesSelect">${p.pages.map(x=>`<option ${x===config.pages?'selected':''}>${x}</option>`).join('')}</select></label>`:''}<div class="summary"><div class="summary-row"><span>Referencia</span><span>${p.detail}</span></div></div><button class="btn btn-primary modal-next" id="nextStep">Continuar con mis fotos <span>→</span></button>`;document.getElementById('sizeSelect').addEventListener('change',e=>config.size=e.target.value);document.getElementById('pagesSelect')?.addEventListener('change',e=>config.pages=e.target.value)}else if(step===2){body.innerHTML=`<p class="eyebrow">Paso 2 de 4</p><h2 class="modal-title">Hazlo tuyo.</h2><p class="modal-subtitle">Sube tus fotos favoritas. Para una impresión nítida, recomendamos archivos JPEG o PNG de buena resolución.</p><label class="upload-zone"><input type="file" id="fileInput" accept="image/jpeg,image/png" multiple><strong>Arrastra tus fotos aquí</strong><span>o haz clic para buscarlas · JPG o PNG</span></label><div class="preview-list" id="previewList"></div>${config.travel?`<label class="field"><span>Destino de la portada</span><input id="destinationInput" value="${config.destination}" placeholder="Ej. Japón, Bali, Australia"></label>`:''}<label class="field"><span>Texto opcional de portada</span><input id="coverText" value="${config.name}" placeholder="Ej. Australia 2026"></label><button class="btn btn-primary modal-next" id="nextStep">Revisar diseño <span>→</span></button>`;const input=document.getElementById('fileInput');input.addEventListener('change',e=>{config.files=[...e.target.files];renderPreviews()});document.getElementById('destinationInput')?.addEventListener('input',e=>config.destination=e.target.value);document.getElementById('coverText').addEventListener('input',e=>config.name=e.target.value)}else if(step===3){body.innerHTML=`<p class="eyebrow">Paso 3 de 4</p><h2 class="modal-title">Una última mirada.</h2><p class="modal-subtitle">Comprueba que tu selección cuenta la historia que quieres guardar.</p><div class="summary"><div class="summary-row"><span>Producto</span><b>${p.title}</b></div><div class="summary-row"><span>Formato</span><b>${config.size}</b></div><div class="summary-row"><span>Acabado</span><b>${config.finish}</b></div>${config.pages?`<div class="summary-row"><span>Páginas</span><b>${config.pages}</b></div>`:''}<div class="summary-row"><span>Fotos</span><b>${config.files.length?config.files.length+' seleccionadas':'Aún puedes continuar sin subir'}</b></div>${config.travel?`<div class="summary-row"><span>Destino</span><b>${config.destination}</b></div>`:''}</div><p class="pay-note">La revisión de resolución se muestra antes de mandar a producción.</p><button class="btn btn-primary modal-next" id="nextStep">Ir a mis datos <span>→</span></button>`}else{body.innerHTML=`<p class="eyebrow">Paso 4 de 4</p><h2 class="modal-title">Casi es tuyo.</h2><p class="modal-subtitle">Déjanos tus datos para preparar el pedido. El pago seguro se abrirá en el siguiente paso.</p><div class="field"><label>Nombre completo</label><input placeholder="Tu nombre"></div><div class="field"><label>Email</label><input type="email" placeholder="tu@email.com"></div><div class="field"><label>Dirección de entrega</label><input placeholder="Dirección, suburbio, estado y código postal"></div><div class="summary"><div class="summary-row"><span>${p.title}</span><b>$${p.price.toFixed(2)} AUD</b></div><div class="summary-row total"><span>Total estimado</span><span>$${p.price.toFixed(2)} AUD</span></div></div><button class="btn btn-primary modal-next" id="payButton">Continuar al pago seguro <span>↗</span></button><p class="pay-note">Stripe / Apple Pay / Google Pay · Demo de checkout lista para conectar</p>`}document.getElementById('nextStep')?.addEventListener('click',()=>{step++;renderStep()});document.getElementById('payButton')?.addEventListener('click',()=>{cart.push({product:p.title,price:p.price,size:config.size});updateCart();closeModal('customizer');openCart()});document.querySelectorAll('.option').forEach(b=>b.addEventListener('click',()=>{config[b.dataset.key]=b.dataset.value;renderStep()}))}
function renderPreviews(){const el=document.getElementById('previewList');if(!el)return;el.innerHTML=config.files.map(f=>`<img alt="${f.name}" src="${URL.createObjectURL(f)}">`).join('')}function updateCart(){document.getElementById('cartCount').textContent=cart.length}function openCart(){const el=document.getElementById('cartBody');el.innerHTML=cart.length?cart.map((item,i)=>`<div class="summary"><div class="summary-row"><b>${item.product}</b><span>$${item.price.toFixed(2)}</span></div><div class="summary-row"><span>${item.size}</span><button class="product-cta remove-item" data-index="${i}">Eliminar</button></div></div>`).join('')+'<button class="btn btn-primary modal-next" id="checkoutButton">Pagar de forma segura <span>↗</span></button><p class="pay-note">Conectaremos este botón con Stripe Checkout para aceptar tarjetas, Apple Pay y Google Pay.</p>':'<div class="empty-cart">Tu carrito todavía está esperando una historia.</div>';openModal('cartModal');el.querySelectorAll('.remove-item').forEach(b=>b.addEventListener('click',()=>{cart.splice(Number(b.dataset.index),1);updateCart();openCart()}));el.querySelector('#checkoutButton')?.addEventListener('click',()=>alert('Demo lista: conecta este botón a Stripe Checkout en producción.'))}document.getElementById('cartButton').addEventListener('click',openCart);
const travelDescriptions={Bali:'Una portada inspirada en arrozales, templos y atardeceres tropicales para guardar una escapada llena de calma y color.',Colombia:'Una composición llena de color para recordar ciudades, montañas, café y todos esos momentos que hacen especial el viaje.',Perú:'Una portada para reunir caminos, historia y paisajes de altura en un libro tan inolvidable como la ruta.',Argentina:'Una historia que va de la energía de Buenos Aires a los paisajes abiertos del sur.',Japón:'Una mezcla de tradición, luz urbana y pequeños detalles para contar tu Japón a tu manera.','Japón · Kyoto':'Templos, jardines y calma para contar una ruta íntima por el Japón tradicional.',Tailandia:'Templos, playas y aventura reunidos en una portada cálida y vibrante.',Roma:'Historia, arte y plazas para guardar una escapada inolvidable por Roma.',Vietnam:'Cultura, sabores y paisajes para convertir tu ruta por Vietnam en un recuerdo para volver a abrir.',Egipto:'Una portada inspirada en el desierto, el Nilo y una historia que atraviesa generaciones.',Australia:'Tu gran aventura local, desde costas y ciudades hasta paisajes que no se olvidan.',Indonesia:'Una colección tropical para guardar islas, agua turquesa y momentos de conexión.',Singapur:'Una portada contemporánea para una ciudad de jardines, arquitectura y descubrimientos.',Italia:'Arte, comida y caminos para convertir tu viaje italiano en un recuerdo para volver.'};
