function travelSpineMm(pageValue){const pages=parseInt(String(pageValue||'').replace(/\D/g,''),10)||20;const layflat=config.bookStyle==='Layflat'||config.bookStyle==='Layflat HD';if(layflat)return pages<=30?9:pages<=60?11:pages<=80?14:17;return pages<=60?9:pages<=80?11:14}
function travelCoverSpec(){return {bleed:'12 mm arriba, abajo y en el borde exterior; 0 mm en la unión con el lomo',spine:travelSpineMm(config.pages)}}
function inspectTravelPhoto(file){return new Promise(resolve=>{const image=new Image();const url=URL.createObjectURL(file);image.onload=()=>{const minSide=Math.min(image.naturalWidth,image.naturalHeight);URL.revokeObjectURL(url);resolve({width:image.naturalWidth,height:image.naturalHeight,minSide,low:minSide<1200,critical:minSide<800})};image.onerror=()=>{URL.revokeObjectURL(url);resolve({width:0,height:0,minSide:0,low:true,critical:true})};image.src=url})}
