let previewIndex=0,previewPages=[];
function renderTravelPreviewPage(){const stage=document.getElementById('travelBookStage'),counter=document.getElementById('travelPageCounter');if(!stage)return;stage.style.backgroundImage=`url("${previewPages[previewIndex]}")`;stage.classList.toggle('travel-book-cover',previewIndex===0);if(counter)counter.textContent=`${previewIndex+1} / ${previewPages.length}`;document.getElementById('travelPrev')?.toggleAttribute('disabled',previewIndex===0);document.getElementById('travelNext')?.toggleAttribute('disabled',previewIndex===previewPages.length-1)}
function openTravelPreview(destination){selectedMomentTheme='';selectedDestination=destination;previewPages=travelPreviewImages[destination]||['https://images.unsplash.com/photo-1521336575822-6da63fb45455?auto=format&fit=crop&w=900&q=86','https://images.unsplash.com/photo-1539367628448-4bc5c9d171c8?auto=format&fit=crop&w=900&q=86'];const front=travelCatalogCoverImages[destination]||previewPages[0],back=previewPages[1]||front;document.querySelector('#travelPreview .eyebrow').textContent='Libro de viaje';document.querySelector('#travelPreview .preview-facts span').textContent='✦ Portada ilustrada del destino';document.getElementById('travelPreviewTitle').textContent=`Libro de viaje · ${destination}`;document.getElementById('travelPreviewDescription').textContent=travelDescriptions[destination]||'Una portada diseñada para comenzar a contar tu viaje.';const visual=document.getElementById('travelPreviewVisual');visual.className='travel-preview-visual';visual.innerHTML=`<div class="travel-auto-flip-wrap"><div class="travel-auto-flip" aria-label="Vista automática de portada y contraportada"><div class="travel-auto-flip-face travel-auto-flip-front" style="background-image:url('${front}')"><span>Libro de viaje · ${destination}</span></div><div class="travel-auto-flip-face travel-auto-flip-back" style="background-image:url('${back}')"><span>Contraportada · ${destination}</span></div></div></div>`;openModal('travelPreview')}
