// PhotobookShop ofrece el floating frame como complemento del canvas, con precio según tamaño.
const canvasFramePrices={'20 × 20 cm':19,'30 × 40 cm':24,'40 × 60 cm':34,'60 × 90 cm':45,'75 × 100 cm':59,'100 × 150 cm':110};
function canvasFramePrice(size){return canvasFramePrices[size]??null}
function injectCanvasFrameOption(){
  if(!currentProduct||currentProduct.id!=='canvas'||step!==1||document.getElementById('floatingFrameOptions'))return;
  const finishGrid=document.querySelector('#customizerBody .option-grid');if(!finishGrid)return;
  const wrap=document.createElement('div'),price=canvasFramePrice(config.size);
  const options=[['Sin marco',0,'Canvas limpio, sin marco flotante','none'],['Negro',price,'Contraste elegante','black'],['Blanco',price,'Acabado luminoso','white'],['Madera natural',price,'Veta visible y cálida','raw']];
  wrap.innerHTML=`<p class="field frame-label"><span>Marco flotante</span></p><div class="option-grid frame-grid" id="floatingFrameOptions">${options.map(([name,cost,desc,swatch])=>`<button class="option frame-option ${config.frame===name?'selected':''}" data-frame="${name}"><span class="frame-swatch frame-${swatch}"></span><strong>${name}</strong><small>${cost===null?'No disponible en este tamaño':cost?'Añadir +$'+cost.toFixed(2)+' AUD':desc}</small></button>`).join('')}</div><p class="pay-note frame-note">Se añade como complemento del Canvas Print y no está disponible en todos los tamaños.</p>`;
  finishGrid.after(wrap);
  wrap.querySelectorAll('[data-frame]').forEach(button=>button.addEventListener('click',()=>{const value=button.dataset.frame;config.frame=value;config.framePrice=value==='Sin marco'?0:canvasFramePrice(config.size);renderStep()}));
}
const fondlyBaseRenderStep=renderStep;
renderStep=function(){
  if(currentProduct&&currentProduct.id==='canvas'){
    currentProduct._basePrice??=currentProduct.price;currentProduct._baseTitle??=currentProduct.title;
    if(!config.frame){config.frame='Sin marco';config.framePrice=0}
    currentProduct.price=step>=3?currentProduct._basePrice+(config.framePrice||0):currentProduct._basePrice;
    currentProduct.title=step>=3&&config.frame&&config.frame!=='Sin marco'?`${currentProduct._baseTitle} · Marco ${config.frame.toLowerCase()}`:currentProduct._baseTitle;
  }
  fondlyBaseRenderStep();
  if(currentProduct&&currentProduct.id==='canvas'&&step===1){injectCanvasFrameOption();document.getElementById('sizeSelect')?.addEventListener('change',()=>renderStep())}
  if(currentProduct&&currentProduct.id==='canvas'&&step>=3){const summary=document.querySelector('#customizerBody .summary');if(summary&&config.frame&&config.frame!=='Sin marco'&&!summary.querySelector('.frame-summary-row')){const row=document.createElement('div');row.className='summary-row frame-summary-row';row.innerHTML=`<span>Marco flotante</span><b>${config.frame}</b>`;const total=summary.querySelector('.total');total?summary.insertBefore(row,total):summary.appendChild(row)}}
};

