function deluxeField(label,key,values){return `<div class="deluxe-field"><p class="field"><span>${label}</span></p><div class="deluxe-choice-grid ${key==='coverMaterial'?'deluxe-material-grid':''}">${values.map((v,i)=>{const [name,img]=Array.isArray(v)?v:[v,''];return `<button type="button" class="deluxe-choice ${config[key]===name?'selected':''}" data-deluxe-key="${key}" data-deluxe-value="${name}">${img?`<img src="${img}" alt="${name}">`:''}<strong>${name}</strong></button>`}).join('')}</div></div>`}
function deluxeMaterialField(){return `<div class="deluxe-field"><p class="field"><span>Material de portada</span></p>${deluxeMaterialGroups.map(([group,values])=>`<div class="deluxe-material-group"><h4>${group}</h4><div class="deluxe-choice-grid deluxe-material-grid">${values.map(([name,img,swatch])=>`<button type="button" class="deluxe-choice ${config.coverMaterial===name?'selected':''}" data-deluxe-key="coverMaterial" data-deluxe-value="${name}">${img?`<img src="${img}" alt="${name}">`:`<span class="deluxe-swatch ${swatch}" role="img" aria-label="${name}"></span>`}<strong>${name}</strong></button>`).join('')}</div></div>`).join('')}</div>`}
function deluxeStampingField(){const values=config.coverMaterial?.startsWith('Leather ·')?['Blind','Silver Foil','Gold Foil','Black Foil','White Foil']:['Silver Foil','Gold Foil','Black Foil','White Foil'];return deluxeField('Stamping','stamping',values)}
function deluxeAccessoryField(){const values=[['Sin accesorio',''],['Slipcase','https://media1.pbwwcdn.net/pages/slipcaseV3.jpg'],['Presentation Box','https://media1.pbwwcdn.net/pages/presentationboxV3.jpg']];return `<div class="deluxe-field"><p class="field"><span>Accesorios</span></p><div class="deluxe-choice-grid deluxe-accessory-grid">${values.map(([name,img])=>`<button type="button" class="deluxe-choice ${config.accessory===name?'selected':''}" data-deluxe-key="accessory" data-deluxe-value="${name}">${img?`<img src="${img}" alt="${name}">`:''}<strong>${name}</strong></button>`).join('')}</div><p class="pay-note accessory-note">El Slipcase o Presentation Box se prepara con el mismo material y estampado elegido para la portada del libro.</p></div>`}
function injectDeluxeOptions(){if(!currentProduct||currentProduct.id!=='deluxe'||step!==1||document.getElementById('deluxeOptions'))return;const summary=document.querySelector('#customizerBody .summary');if(!summary)return;const wrap=document.createElement('div');wrap.id='deluxeOptions';wrap.innerHTML=deluxeField('Papel disponible','paper',['Fedrigoni Free Life Satin 150gsm','Felix Schoeller E-Photo Lustre 190gsm','Felix Schoeller E-Photo Matte 190gsm','Felix Schoeller E-Photo Lustre 190gsm · ColorUp!'])+deluxeMaterialField()+deluxeStampingField()+deluxeField('Tipografía','font',['Helvetica · 14 points','Helvetica · 36 points','Optima · 36 points'])+deluxeAccessoryField()+'<p class="pay-note">Las cubiertas y accesorios están sujetos a disponibilidad al finalizar el pedido.</p>';summary.before(wrap);wrap.querySelectorAll('[data-deluxe-key]').forEach(b=>b.addEventListener('click',()=>{config[b.dataset.deluxeKey]=b.dataset.deluxeValue;renderStep()}));}
const fondlyDeluxeRenderStep=renderStep;
renderStep=function(){if(currentProduct&&currentProduct.id==='deluxe'&&!config.coverMaterial?.startsWith('Leather ·')&&config.stamping==='Blind')config.stamping='Gold Foil';fondlyDeluxeRenderStep();if(currentProduct&&currentProduct.id==='deluxe'){if(step===1){injectDeluxeOptions();const finishLabel=[...document.querySelectorAll('#customizerBody .field span')].find(el=>el.textContent==='Acabado');if(finishLabel)finishLabel.textContent='Encuadernación';const finishOption=document.querySelector('#customizerBody .finish-option small');if(finishOption)finishOption.textContent='Apertura completamente plana, ideal para panoramas'}if(step>=3){const summary=document.querySelector('#customizerBody .summary');if(summary&&!summary.querySelector('.deluxe-summary-row')){['paper','coverMaterial','stamping','font','accessory'].forEach(key=>{const row=document.createElement('div');row.className='summary-row deluxe-summary-row';row.innerHTML=`<span>${({paper:'Papel',coverMaterial:'Portada',stamping:'Stamping',font:'Tipografía',accessory:'Accesorios'})[key]}</span><b>${config[key]}</b>`;summary.appendChild(row)})}}if(step===4){const rows=document.querySelectorAll('#customizerBody .summary-row');rows[0]?.lastElementChild&&(rows[0].lastElementChild.textContent='Según configuración');rows[rows.length-1]?.lastElementChild&&(rows[rows.length-1].lastElementChild.textContent='Se confirma al finalizar')}}}
