const fondlyCoasterRenderStep=renderStep;
function injectCoasterOptions(){if(!currentProduct||currentProduct.id!=='coasters'||step!==1||document.getElementById('coasterOptions'))return;const summary=document.querySelector('#customizerBody .summary');if(!summary)return;const wrap=document.createElement('div');wrap.id='coasterOptions';const field=(label,key,values)=>`<div class="coaster-field"><p class="field"><span>${label}</span></p><div class="deluxe-choice-grid coaster-choice-grid">${values.map(v=>`<button type="button" class="deluxe-choice ${config[key]===v?'selected':''}" data-coaster-key="${key}" data-coaster-value="${v}"><strong>${v}</strong></button>`).join('')}</div></div>`;const accessoryField=`<div class="coaster-field"><p class="field"><span>Accesorio · soporte de pino</span></p><div class="coaster-accessory-reference"><img src="assets/coasters/holder-slots.png" alt="Referencia de soportes para 4, 6 y 8 posavasos"></div><div class="deluxe-choice-grid coaster-accessory-grid">${['Sin soporte','Soporte para 4','Soporte para 6','Soporte para 8'].map(name=>`<button type="button" class="deluxe-choice ${config.holder===name?'selected':''}" data-coaster-key="holder" data-coaster-value="${name}"><strong>${name}</strong></button>`).join('')}</div></div>`;wrap.innerHTML=field('Forma','shape',['Square','Flor'])+field('Cantidad','pack',['Single','Set of 2','Set of 4','Set of 6','Set of 8'])+accessoryField+'<p class="pay-note">El soporte de pino es opcional y se añade al carrito. Para pedidos de 21 piezas o más, solicita una cotización especial.</p>';summary.before(wrap);wrap.querySelectorAll('[data-coaster-key]').forEach(b=>b.addEventListener('click',()=>{config[b.dataset.coasterKey]=b.dataset.coasterValue;renderStep()}))}
renderStep=function(){fondlyCoasterRenderStep();if(currentProduct&&currentProduct.id==='coasters'){if(step===1){const finishGrid=document.querySelector('#customizerBody .finish-option')?.closest('.option-grid');const finishField=finishGrid?.previousElementSibling;finishGrid?.remove();finishField?.remove();if(!document.getElementById('coasterDetails')){const detail=document.createElement('div');detail.id='coasterDetails';detail.className='coaster-details';detail.innerHTML='<h4>Detalles del producto</h4><div><span>Tamaño</span><b>3.75 × 3.75 in (95 × 95 mm)</b></div><div><span>Acabado</span><b>Gloss coating</b></div><div><span>Material</span><b>Compuesto de madera de 3 mm con respaldo de corcho antideslizante</b></div><div><span>Nota</span><b>Pedidos de 21 piezas o más: solicita una cotización especial.</b></div>';document.querySelector('#customizerBody .summary')?.before(detail)}injectCoasterOptions()}if(step>=3){const summary=document.querySelector('#customizerBody .summary');if(summary&&!summary.querySelector('.coaster-summary-row')){[['Forma',config.shape],['Cantidad',config.pack],['Soporte',config.holder]].forEach(([label,value])=>{const row=document.createElement('div');row.className='summary-row coaster-summary-row';row.innerHTML=`<span>${label}</span><b>${value}</b>`;summary.appendChild(row)})}}}}
