function injectCoasterGallery(){if(document.getElementById('coasterGallery'))return;const details=document.getElementById('coasterDetails'),options=document.getElementById('coasterOptions');if(!details||!options)return;const images=coasterGalleryImages[config.shape]||coasterGalleryImages.Square;const gallery=document.createElement('div');gallery.id='coasterGallery';gallery.className='coaster-gallery';gallery.innerHTML=`<div class="coaster-gallery-main"><img src="${images[0]}" alt="${config.shape} · vista principal" id="coasterGalleryMain"></div><div class="coaster-gallery-thumbs">${images.map((src,i)=>`<button type="button" class="coaster-gallery-thumb ${i===0?'selected':''}" data-gallery-src="${src}" aria-label="Ver imagen ${i+1} de ${config.shape}"><img src="${src}" alt=""></button>`).join('')}</div>`;options.querySelector('.coaster-field')?.after(gallery);gallery.querySelectorAll('[data-gallery-src]').forEach(btn=>btn.addEventListener('click',()=>{gallery.querySelector('#coasterGalleryMain').src=btn.dataset.gallerySrc;gallery.querySelectorAll('.coaster-gallery-thumb').forEach(x=>x.classList.remove('selected'));btn.classList.add('selected')}))}
renderStep=function(){fondlyCoasterLayoutRenderStep();if(currentProduct&&currentProduct.id==='coasters'&&step===1){const sizeField=document.querySelector('#customizerBody #sizeSelect')?.closest('.field');sizeField?.remove();const details=document.getElementById('coasterDetails'),options=document.getElementById('coasterOptions');const size=config.shape==='Flor'?'3.66 × 3.66 in (93 × 93 mm)':'3.75 × 3.75 in (95 × 95 mm)';if(details){const sizeValue=[...details.querySelectorAll('div')].find(row=>row.querySelector('span')?.textContent==='Tamaño')?.querySelector('b');if(sizeValue)sizeValue.textContent=size;if(options){const first=options.querySelector('.coaster-field');first?.after(details)}}injectCoasterGallery()}}
const productGalleryImages={canvas:['https://www.photobookshop.com.au/rv2/img/main/web_menu_canvas.jpg','https://images.unsplash.com/photo-1561214115-f2f134cc4912?auto=format&fit=crop&w=900&q=85','https://images.unsplash.com/photo-1549490349-8643362247b5?auto=format&fit=crop&w=900&q=85'],tiles:['https://www.photobookshop.com.au/responsive/img/productpages/0/tiles/grid/phototiles-stick.jpg','https://images.unsplash.com/photo-1561214115-f2f134cc4912?auto=format&fit=crop&w=900&q=85','https://images.unsplash.com/photo-1577083288073-40892c0860a4?auto=format&fit=crop&w=900&q=85'],acrylic:['https://www.photobookshop.com.au/rv2/img/pages/1664257197_f70_f55.jpg','https://images.unsplash.com/photo-1561214115-f2f134cc4912?auto=format&fit=crop&w=900&q=85','https://images.unsplash.com/photo-1541961017774-22349e4a1262?auto=format&fit=crop&w=900&q=85'],mug:['https://www.photobookshop.com.au/responsive/img/productpages/0/gifts/mug-photo.jpg','https://images.unsplash.com/photo-1514228742587-6b1558fcca3d?auto=format&fit=crop&w=900&q=85','https://images.unsplash.com/photo-1495474472287-4d71bcdd2085?auto=format&fit=crop&w=900&q=85'],magnets:['https://www.photobookshop.com.au/rv2/img/pages/1731559287_f89_f39.jpg','https://images.unsplash.com/photo-1604594849809-dfedbc827105?auto=format&fit=crop&w=900&q=85','https://images.unsplash.com/photo-1582561833407-b95380302c47?auto=format&fit=crop&w=900&q=85'],hardcover:['https://www.photobookshop.com.au/rv2/img/pages/1664243760_f84_f23.jpg','https://images.unsplash.com/photo-1544947950-fa07a98d237f?auto=format&fit=crop&w=900&q=85','https://images.unsplash.com/photo-1521587760476-6c12a4b040da?auto=format&fit=crop&w=900&q=85'],layflat:['https://www.photobookshop.com.au/responsive/img/index/pc-joinspin.jpg','https://images.unsplash.com/photo-1543002588-bfa74002ed7e?auto=format&fit=crop&w=900&q=85','https://images.unsplash.com/photo-1512820790803-83ca734da794?auto=format&fit=crop&w=900&q=85'],hdlayflat:['https://www.photobookshop.com.au/responsive/img/productpages/0/photobooks/premium440gsm.jpg','https://images.unsplash.com/photo-1543002588-bfa74002ed7e?auto=format&fit=crop&w=900&q=85','https://images.unsplash.com/photo-1532012197267-da84d127e765?auto=format&fit=crop&w=900&q=85'],deluxe:['https://media1.pbwwcdn.net/pages/deluxe-photobook/01-DeluxePhotobook-4.jpg','https://images.unsplash.com/photo-1544947950-fa07a98d237f?auto=format&fit=crop&w=900&q=85','https://images.unsplash.com/photo-1524995997946-a1c2e315a42f?auto=format&fit=crop&w=900&q=85']};
function injectProductGallery(){if(!currentProduct||!productGalleryImages[currentProduct.id]||step!==1||document.getElementById('productGallery'))return;const summary=document.querySelector('#customizerBody .summary');if(!summary)return;const images=productGalleryImages[currentProduct.id],gallery=document.createElement('div');gallery.id='productGallery';gallery.className='coaster-gallery product-gallery';gallery.innerHTML=`<div class="coaster-gallery-main"><img src="${images[0]}" alt="${currentProduct.title} · vista principal" id="productGalleryMain"></div><div class="coaster-gallery-thumbs">${images.map((src,i)=>`<button type="button" class="coaster-gallery-thumb ${i===0?'selected':''}" data-product-gallery-src="${src}" aria-label="Ver imagen ${i+1} de ${currentProduct.title}"><img src="${src}" alt=""></button>`).join('')}</div>`;summary.before(gallery);gallery.querySelectorAll('[data-product-gallery-src]').forEach(btn=>btn.addEventListener('click',()=>{gallery.querySelector('#productGalleryMain').src=btn.dataset.productGallerySrc;gallery.querySelectorAll('.coaster-gallery-thumb').forEach(x=>x.classList.remove('selected'));btn.classList.add('selected')}))}
const fondlyProductGalleryRenderStep=renderStep;
renderStep=function(){fondlyProductGalleryRenderStep();if(currentProduct&&currentProduct.id!=='coasters'&&productGalleryImages[currentProduct.id]&&step===1)injectProductGallery()}
const fondlyGalleryFirstRenderStep=renderStep;
renderStep=function(){fondlyGalleryFirstRenderStep();if(step===1){const body=document.getElementById('customizerBody'),gallery=body?.querySelector('#coasterGallery, #productGallery');if(body&&gallery)body.prepend(gallery)}}

// Editor de páginas para libros de viaje: dos rutas (IA o manual) con edición posterior.
const travelTemplates=[['full','Foto completa'],['split','Dos fotos'],['triptych','Tríptico'],['story','Foto + texto']];
const travelEditorBackgrounds=[['#ffffff','Blanco'],['#fff4f6','Rosa suave'],['#f4eee8','Arena'],['#5B122E','Burdeos']];
function travelEditorPreview(){const template=config.travelPageTemplates?.[config.travelPageIndex||0]||config.travelTemplate||'full',bg=config.travelBackground||'#ffffff',files=config.files||[],backText=config.backText||'';const photos=files.length?files.slice(0,4).map((f,i)=>`<img src="${URL.createObjectURL(f)}" alt="Foto ${i+1}">`).join(''):'<span class="travel-empty-page">Tus fotos aparecerán aquí</span>';return `<div class="travel-editor-cover-preview"><div class="travel-editor-cover-mini travel-cover-art" style="background-image:url('${travelCoverImage()}')"></div><div class="travel-editor-cover-copy"><b>Portada y contraportada guardadas</b><span>${backText||'Sin frase de contraportada'}</span></div></div><div class="travel-page-preview" style="background:${bg}"><div class="travel-page-layout travel-layout-${template}">${photos}</div>${template==='story'?'<p class="travel-page-caption">Un momento para volver a mirar</p>':''}</div>`}
function renderTravelDesigner(){const body=document.getElementById('customizerBody');if(!body)return;const files=config.files||[];body.innerHTML=`<p class="eyebrow">Paso 2 de 4 · ${config.designMode==='ai'?'Propuesta con IA':'Editor de páginas'}</p><h2 class="modal-title">Diseña tu libro de Bali.</h2><p class="modal-subtitle">Puedes aceptar una propuesta inicial y después cambiar fotos, plantillas, fondos y textos.</p><div class="travel-editor-toolbar"><div><strong>Plantilla de esta página</strong><div class="travel-template-row">${travelTemplates.map(([id,label])=>`<button type="button" class="travel-template ${config.travelTemplate===id?'selected':''}" data-travel-template="${id}">${label}</button>`).join('')}</div></div><div><strong>Fondo</strong><div class="travel-background-row">${travelEditorBackgrounds.map(([color,label])=>`<button type="button" class="travel-background ${config.travelBackground===color?'selected':''}" style="background:${color}" title="${label}" aria-label="Fondo ${label}" data-travel-background="${color}"></button>`).join('')}</div></div></div><div class="travel-editor-workspace"><aside class="travel-upload-panel"><strong>Tus fotos</strong><label class="upload-zone travel-upload-zone"><input type="file" id="travelFileInput" accept="image/jpeg,image/png" multiple><span>Arrastra o selecciona fotos</span><small>JPG o PNG · puedes añadir más después</small></label><div class="travel-photo-list">${files.length?files.map((f,i)=>`<div class="travel-photo-chip"><img src="${URL.createObjectURL(f)}" alt=""><span>${f.name}</span></div>`).join(''):'<small>Aún no has añadido fotos.</small>'}</div><button type="button" class="text-link" id="travelBackToModes">Cambiar método</button></aside><section class="travel-pages-panel"><div class="travel-pages-header"><strong>Vista previa editable</strong><span>${config.designMode==='ai'?'La IA creó una primera propuesta':'Arrastra tus fotos a una plantilla'}</span></div>${travelEditorPreview()}<div class="travel-page-controls"><label>Páginas <select id="travelPagesSelect">${currentProduct.pages.map(x=>`<option ${x===config.pages?'selected':''}>${x}</option>`).join('')}</select></label><button type="button" class="text-link" id="addTravelPage">Añadir página</button></div></section></div><button class="btn btn-primary modal-next" id="nextStep">Continuar con la revisión <span>→</span></button>`;body.querySelectorAll('[data-travel-template]').forEach(b=>b.addEventListener('click',()=>{config.travelTemplate=b.dataset.travelTemplate;renderTravelDesigner()}));body.querySelectorAll('[data-travel-background]').forEach(b=>b.addEventListener('click',()=>{config.travelBackground=b.dataset.travelBackground;renderTravelDesigner()}));document.getElementById('travelFileInput').addEventListener('change',e=>{config.files=[...(config.files||[]),...e.target.files];config.files=config.files.slice(0,30);renderTravelDesigner()});document.getElementById('travelPagesSelect').addEventListener('change',e=>{config.pages=e.target.value});document.getElementById('addTravelPage').addEventListener('click',()=>{const values=currentProduct.pages,index=values.indexOf(config.pages);config.pages=values[Math.min(index+1,values.length-1)];renderTravelDesigner()});document.getElementById('travelBackToModes').addEventListener('click',()=>{config.designMode='chooser';renderTravelDesignModes()});document.getElementById('nextStep').addEventListener('click',()=>{step++;renderStep()})}
function renderTravelDesignModes(){const body=document.getElementById('customizerBody');if(!body)return;body.innerHTML=`<p class="eyebrow">Paso 2 de 4</p><h2 class="modal-title">Diseña las páginas de tu viaje.</h2><p class="modal-subtitle">Elige cómo quieres empezar. En ambos casos podrás editar el resultado antes de continuar.</p><div class="travel-design-modes"><button type="button" class="travel-design-mode" id="travelAiMode"><span class="travel-mode-icon">✦</span><strong>Diseñar con IA</strong><small>Sube tus fotos y recibe una propuesta de páginas organizada por momentos y formatos.</small></button><button type="button" class="travel-design-mode" id="travelManualMode"><span class="travel-mode-icon">＋</span><strong>Diseñar por mi cuenta</strong><small>Elige plantillas, arrastra tus fotos y decide fondos, textos y composición.</small></button></div><div id="travelModePanel"></div>`;document.getElementById('travelAiMode').addEventListener('click',()=>{config.designMode='ai';renderTravelModePanel()});document.getElementById('travelManualMode').addEventListener('click',()=>{config.designMode='manual';renderTravelModePanel()})}
function renderTravelModePanel(){const panel=document.getElementById('travelModePanel');if(!panel)return;const ai=config.designMode==='ai';panel.innerHTML=`<div class="travel-mode-panel"><strong>${ai?'Empieza con tus fotos':'Prepara tu espacio de diseño'}</strong><p>${ai?'La IA necesita tus fotos para crear una primera propuesta. Después podrás cambiar cualquier detalle.':'Añade tus fotos y abre el editor para elegir una plantilla por página.'}</p><label class="upload-zone travel-upload-zone"><input type="file" id="travelModeFileInput" accept="image/jpeg,image/png" multiple><strong>Arrastra tus fotos aquí</strong><span>o haz clic para buscarlas · JPG o PNG</span></label><div class="preview-list" id="travelModePreviews">${(config.files||[]).map(f=>`<img alt="${f.name}" src="${URL.createObjectURL(f)}">`).join('')}</div><button type="button" class="btn btn-primary" id="travelContinueDesign">${ai?'Crear propuesta con IA':'Abrir editor manual'} <span>→</span></button></div>`;document.getElementById('travelModeFileInput').addEventListener('change',e=>{config.files=[...(config.files||[]),...e.target.files];config.files=config.files.slice(0,30);renderTravelModePanel()});document.getElementById('travelContinueDesign').addEventListener('click',()=>{config.designMode=ai?'ai':'manual';config.travelTemplate=config.travelTemplate||'full';config.travelBackground=config.travelBackground||'#ffffff';renderTravelDesigner()})}
const fondlyTravelDesignRenderStep=renderStep;
renderStep=function(){if(config?.travel&&step===2){config.designMode=config.designMode||'chooser';if(config.designMode==='chooser')renderTravelDesignModes();else renderTravelDesigner();return}fondlyTravelDesignRenderStep()}

// Catálogo simplificado: se muestran solo Viajes, Momentos y Luxury dentro de Fotolibros.
products.find(p=>p.id==='deluxe').title='Libros Luxury';
const fondlyCatalogRenderProducts=renderProducts;
renderProducts=function(filter='all'){fondlyCatalogRenderProducts(filter);['hardcover','layflat','hdlayflat'].forEach(id=>document.querySelector(`.product-card [data-product="${id}"]`)?.closest('.product-card')?.remove());document.querySelector('.product-card [data-product="deluxe"]')?.closest('.product-card')?.querySelector('.product-price')?.replaceChildren(document.createTextNode('Precio según configuración'))};

const decorProductIds=['canvas','tiles','acrylic'];
const giftsProductIds=['mug','coasters','magnets'];
function renderCatalogRail(id,heading,eyebrow,description,productIds,show=false){
  const rail=document.getElementById(id);if(!rail)return;
  if(!show){rail.hidden=true;rail.innerHTML='';return}
  rail.hidden=false;
  rail.innerHTML=`<div class="travel-product-heading"><div><p class="eyebrow">${eyebrow}</p><h3>${heading}</h3></div><p>${description}</p></div><div class="travel-product-scroller">${productIds.map(productId=>{const product=products.find(p=>p.id===productId),image=productGalleryImages[productId]?.[0]||'';return `<article class="travel-product-card catalog-product-card"><button type="button" class="travel-product-cover catalog-product-cover" style="background-image:url('${image}')" data-catalog-product="${productId}" aria-label="Ver ${product.title}"></button><div class="travel-product-info"><h4>${product.title}</h4><small class="travel-product-tag">${product.desc}</small><div class="travel-product-meta"><b>Desde $${product.price.toFixed(2)} AUD</b><button type="button" class="travel-product-create" data-catalog-product="${productId}">Personalizar <span>↗</span></button></div></div></article>`}).join('')}</div>`;
  rail.querySelectorAll('[data-catalog-product]').forEach(button=>button.addEventListener('click',()=>openCustomizer(button.dataset.catalogProduct)));
}
const fondlyCatalogRailRenderProducts=renderProducts;
renderProducts=function(filter='all'){
  fondlyCatalogRailRenderProducts(filter);
  const all=filter==='all';
  (all||['decor','gifts'].includes(filter))&&document.querySelectorAll('.product-card').forEach(card=>card.remove());
  renderTravelProductRail(all||filter==='books');
  renderMomentProductRail(all||filter==='books');
  renderLuxuryProductRail(all||filter==='books');
  renderCatalogRail('decorProductRail','Elige una pieza para tu pared','Decoración','Fotografías convertidas en piezas para vestir tus espacios con recuerdos que sí quieres ver todos los días.',decorProductIds,all||filter==='decor');
  renderCatalogRail('giftsProductRail','Regalos hechos para alguien especial','Regalos personalizados','Detalles pensados para celebrar, agradecer y convertir una foto en algo que se puede regalar.',giftsProductIds,all||filter==='gifts');
};

const luxuryProductThemes=[
  ['Luxury Slip','Un libro de lujo para guardar votos, fotografías y el capítulo de una vida compartida.','assets/luxury/luxury-slip-cover.png'],
  ['Luxury Box','Una pieza premium para celebrar aniversarios, familia, viajes y recuerdos que merecen durar.','assets/luxury/luxury-box-cover.png']
];
function openLuxuryTheme(theme){openCustomizer('deluxe');currentProduct.title=theme;config.luxuryTheme=theme;renderStep()}
function renderLuxuryProductRail(show=false){
  const rail=document.getElementById('luxuryProductRail');
  if(!rail)return;
  if(!show){rail.hidden=true;rail.innerHTML='';return}
  rail.hidden=false;
  rail.innerHTML=`<div class="travel-product-heading"><div><p class="eyebrow">Fotolibros · Luxury</p><h3>Elige tu edición especial</h3></div><p>Dos formas de convertir tus recuerdos en un libro artesanal con materiales premium y acabados personalizados.</p></div><div class="travel-product-scroller">${luxuryProductThemes.map(([name,tag,image])=>`<article class="travel-product-card luxury-product-card"><button type="button" class="travel-product-cover luxury-product-cover" style="background-image:url('${image}')" data-luxury-product="${name}" aria-label="Ver portada de ${name}"></button><div class="travel-product-info"><h4>${name}</h4><small class="travel-product-tag">${tag}</small><div class="travel-product-meta"><b>Precio según configuración</b><button type="button" class="travel-product-create" data-luxury-product="${name}">Crear libro <span>↗</span></button></div></div></article>`).join('')}</div>`;
  rail.querySelectorAll('[data-luxury-product]').forEach(button=>button.addEventListener('click',()=>openLuxuryTheme(button.dataset.luxuryProduct)));
}
const fondlyLuxuryProductRenderProducts=renderProducts;
renderProducts=function(filter='all'){
  fondlyLuxuryProductRenderProducts(filter);
  if(filter==='books')document.querySelector('.product-card [data-product="deluxe"]')?.closest('.product-card')?.remove();
  renderLuxuryProductRail(filter==='books');
};

