let activeMomentCategory='Wedding';
const momentCategoryFor=name=>name==='Nuestra boda'||name.startsWith('Wedding ·')?'Wedding':name==='Amor'?'Amor':'Mis momentos';
const momentCoverParts=Object.fromEntries(momentProductThemes.map(([name,,front,back])=>[name,{front,back,spine:'assets/travel/covers/bali-spine.png'}]));
function openMomentTheme(theme){
  selectedMomentTheme=theme;
  const item=momentProductThemes.find(([name])=>name===theme)||[];
  const front=item[2]||'assets/moments/boda-front.png',back=item[3]||front;
  document.querySelector('#travelPreview .eyebrow').textContent='Fotolibro · Momentos';
  document.getElementById('travelPreviewTitle').textContent='Wedding';
  document.getElementById('travelPreviewDescription').textContent='Elige una portada Wedding y personalízala con tus propias fotos y textos.';
  document.querySelector('#travelPreview .preview-facts span').textContent='✦ Portada ilustrada de la colección';
  const visual=document.getElementById('travelPreviewVisual');visual.className='travel-preview-visual';visual.innerHTML=`<div class="travel-auto-flip-wrap"><div class="travel-auto-flip" aria-label="Vista automática de portada y contraportada"><div class="travel-auto-flip-face travel-auto-flip-front" style="background-image:url('${front}')"><span>Wedding</span></div><div class="travel-auto-flip-face travel-auto-flip-back" style="background-image:url('${back}')"><span>Contraportada</span></div></div></div>`;
  openModal('travelPreview');
}
function renderMomentProductRail(show=false){
  const rail=document.getElementById('momentProductRail');
  if(!rail)return;
  if(!show){rail.hidden=true;rail.innerHTML='';return}
  rail.hidden=false;
  const categories=['Wedding','Amor','Mis momentos'];
  const visibleThemes=momentProductThemes.filter(([name])=>momentCategoryFor(name)===activeMomentCategory);
  const momentCards=visibleThemes.length?visibleThemes.map(([name,tag,image,back])=>`<article class="travel-product-card moment-product-card ${activeMomentCategory==='Wedding'?'moment-wedding-card':''}"><button type="button" class="travel-product-cover moment-product-cover" data-moment-product="${name}" aria-label="Ver portada de ${activeMomentCategory==='Wedding'?'Wedding':name}"><span class="travel-cover-flip"><span class="travel-cover-face travel-cover-front" style="background-image:url('${image}')"></span><span class="travel-cover-face travel-cover-back" style="background-image:url('${back}')"></span></span></button><div class="travel-product-info"><h4>${activeMomentCategory==='Wedding'?'Wedding':name}</h4><small class="travel-product-tag">${tag}</small><div class="travel-product-meta"><b>Desde $49.95 AUD</b><button type="button" class="travel-product-create" data-moment-product="${name}">Crear libro <span>↗</span></button></div></div></article>`).join(''):`<p class="moment-empty">Próximamente añadiremos nuevas portadas a esta categoría.</p>`;
  rail.innerHTML=`<div class="travel-product-heading"><div><p class="eyebrow">Fotolibros · Momentos</p><h3>Elige la historia que quieres guardar</h3></div><p>Portadas para celebrar los capítulos importantes. Selecciona una y empieza a crear tu libro.</p></div><div class="moment-category-tabs" role="tablist" aria-label="Categorías de momentos">${categories.map(category=>`<button type="button" class="moment-category-tab ${category===activeMomentCategory?'active':''}" data-moment-category="${category}" role="tab" aria-selected="${category===activeMomentCategory}">${category}</button>`).join('')}</div><div class="travel-product-scroller">${momentCards}</div>`;
  rail.querySelectorAll('[data-moment-category]').forEach(button=>button.addEventListener('click',()=>{activeMomentCategory=button.dataset.momentCategory;renderMomentProductRail(true)}));
  rail.querySelectorAll('[data-moment-product]').forEach(button=>button.addEventListener('click',()=>openMomentTheme(button.dataset.momentProduct)));
}
const fondlyMomentProductRenderProducts=renderProducts;
renderProducts=function(filter='all'){
  fondlyMomentProductRenderProducts(filter);
  renderMomentProductRail(filter==='books');
};
